import { describe, expect, it } from 'vitest';

import { decodeRunContextRef, encodeRunContextRef } from '../index.js';

describe('@jini-ai/protocol — run-context', () => {
  it('round-trips a prompt-only payload', () => {
    const ref = encodeRunContextRef({ payload: { prompt: 'what time is it?' } });
    expect(decodeRunContextRef({ contextRef: ref })).toEqual({ prompt: 'what time is it?' });
  });

  it('round-trips a prompt with history', () => {
    const history = [{ role: 'user', text: 'hi' }, { role: 'assistant', text: 'hello' }];
    const ref = encodeRunContextRef({ payload: { prompt: 'continue', history } });
    expect(decodeRunContextRef({ contextRef: ref })).toEqual({ prompt: 'continue', history });
  });

  it('round-trips an empty payload', () => {
    const ref = encodeRunContextRef({ payload: {} });
    expect(decodeRunContextRef({ contextRef: ref })).toEqual({});
  });

  it('carries a stable, recognizable prefix', () => {
    const ref = encodeRunContextRef({ payload: { prompt: 'x' } });
    expect(ref.startsWith('jini-run-context:v1:')).toBe(true);
  });

  it('returns undefined for a contextRef with no jini-run-context prefix (a host\'s own opaque scheme)', () => {
    expect(decodeRunContextRef({ contextRef: 'playground:starter-site:some-blob' })).toBeUndefined();
    expect(decodeRunContextRef({ contextRef: 'just some opaque string' })).toBeUndefined();
  });

  it('returns undefined for a prefixed but malformed JSON payload', () => {
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:{not json' })).toBeUndefined();
  });

  it('returns undefined when the parsed payload is not a plain object', () => {
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:["array", "not", "object"]' })).toBeUndefined();
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:"just a string"' })).toBeUndefined();
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:42' })).toBeUndefined();
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:null' })).toBeUndefined();
  });

  it('returns undefined when prompt is present but not a string', () => {
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:{"prompt":42}' })).toBeUndefined();
  });

  it('returns undefined when history is present but not an array', () => {
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:{"history":"nope"}' })).toBeUndefined();
  });

  it('ignores unknown extra fields in the decoded payload rather than rejecting them', () => {
    const decoded = decodeRunContextRef({ contextRef: 'jini-run-context:v1:{"prompt":"hi","extra":"ignored"}' });
    expect(decoded).toEqual({ prompt: 'hi' });
  });

  it('returns undefined for a prefix carrying a different version', () => {
    // The `:v1:` segment exists so a future encoding can coexist; a v2 payload must not be
    // mis-parsed as v1 just because the leading segment matches.
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v2:{"prompt":"x"}' })).toBeUndefined();
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:{"prompt":"x"}' })).toBeUndefined();
  });

  it('returns undefined for the bare prefix with no payload at all', () => {
    expect(decodeRunContextRef({ contextRef: 'jini-run-context:v1:' })).toBeUndefined();
  });

  it('preserves present-but-falsy fields rather than collapsing them to absent', () => {
    // `''` and `[]` are meaningfully different from omitted — a truthiness check in place of the
    // `=== undefined` check would silently drop both.
    expect(decodeRunContextRef({ contextRef: encodeRunContextRef({ payload: { prompt: '' } }) })).toEqual({ prompt: '' });
    expect(decodeRunContextRef({ contextRef: encodeRunContextRef({ payload: { history: [] } }) })).toEqual({ history: [] });
  });

  it('round-trips unicode, escapes and a prompt containing the prefix itself', () => {
    const prompt = 'emoji 🚀 / CJK 日本語 / quote " / backslash \\ / newline \n / tab \t / �';
    expect(decodeRunContextRef({ contextRef: encodeRunContextRef({ payload: { prompt } }) })).toEqual({ prompt });

    const nested = { prompt: 'jini-run-context:v1:{"prompt":"not really nested"}' };
    expect(decodeRunContextRef({ contextRef: encodeRunContextRef({ payload: nested }) })).toEqual(nested);
  });

  it('round-trips nested history entries without flattening them', () => {
    const history = [
      { role: 'user', parts: [{ type: 'text', text: 'hi' }] },
      { role: 'assistant', meta: { tokens: 12, tags: ['a', 'b'], done: true, err: null } },
    ];
    expect(decodeRunContextRef({ contextRef: encodeRunContextRef({ payload: { history } }) })).toEqual({ history });
  });

  it('does not let a __proto__ or constructor key in the payload pollute a prototype', () => {
    const polluting = 'jini-run-context:v1:{"__proto__":{"polluted":true},"constructor":{"prototype":{"polluted":true}},"prompt":"hi"}';
    const decoded = decodeRunContextRef({ contextRef: polluting });

    expect(decoded).toEqual({ prompt: 'hi' });
    expect(Object.getPrototypeOf(decoded)).toBe(Object.prototype);
    expect(Object.prototype.hasOwnProperty.call(decoded!, '__proto__')).toBe(false);
    expect(Object.prototype.hasOwnProperty.call(decoded!, 'constructor')).toBe(false);
    expect(({} as Record<string, unknown>).polluted).toBeUndefined();
    expect(Object.prototype.hasOwnProperty.call(Object.prototype, 'polluted')).toBe(false);
  });
});

